let SITE_CONFIG={social:{facebook:"#",twitter:"#",instagram:"#",linkedin:"#",youtube:"#"},contact:{email:"kdtekh@gmail.com",phone:"+34 987 654 321",address:"Calle Falsa 123, 28001 Madrid, España",schedule:"Lunes a Viernes: 9:00 - 18:00 | Sábados: 10:00 - 14:00"},menu:[{title:"Inicio",url:"/"},{title:"Cursos",url:"#"},{title:"Blog",url:"/blog.html"},{title:"Contacto",url:"/contacto.html"}],courses:[{title:"Programación",url:"/categorias/programacion.html"},{title:"Ciberseguridad",url:"/categorias/ciberseguridad.html"},{title:"Redes",url:"/categorias/redes.html"},{title:"Base de Datos",url:"/categorias/basedatos.html"},{title:"Ofimática",url:"/categorias/ofimatica.html"},{title:"Diseño Gráfico",url:"/categorias/diseno.html"}]};function renderFooter(){var a=(new Date).getFullYear();return`
    <div class="footer-content">
        <div class="footer-section about">
            <img src="/img/logo.png" alt="KDTekh Logo" class="footer-logo" style="border-radius: 15px; width: 180px; height: auto;">
            <p>Formación tecnológica de calidad para el futuro digital.</p>
            <div class="contact">
                <span><i class="fas fa-map-marker-alt"></i> ${SITE_CONFIG.contact.address}</span>
                <span><i class="fas fa-phone"></i> ${SITE_CONFIG.contact.phone}</span>
                <span><i class="fas fa-envelope"></i> ${SITE_CONFIG.contact.email}</span>
            </div>
            <div class="socials">
                <a href="${SITE_CONFIG.social.facebook}" target="_blank" aria-label="Facebook"><i class="fab fa-facebook-f"></i></a>
                <a href="${SITE_CONFIG.social.twitter}" target="_blank" aria-label="Twitter"><i class="fab fa-twitter"></i></a>
                <a href="${SITE_CONFIG.social.instagram}" target="_blank" aria-label="Instagram"><i class="fab fa-instagram"></i></a>
                <a href="${SITE_CONFIG.social.linkedin}" target="_blank" aria-label="LinkedIn"><i class="fab fa-linkedin-in"></i></a>
                <a href="${SITE_CONFIG.social.youtube}" target="_blank" aria-label="YouTube"><i class="fab fa-youtube"></i></a>
            </div>
        </div>

        <div class="footer-section links">
            <h3>Enlaces Rápidos</h3>
            <ul>
                ${SITE_CONFIG.menu.map(a=>`<li><a href="${a.url}">${a.title}</a></li>`).join("")}
            </ul>
        </div>

        <div class="footer-section courses">
            <h3>Cursos</h3>
            <ul>
                ${SITE_CONFIG.courses.map(a=>`<li><a href="${a.url}">${a.title}</a></li>`).join("")}
            </ul>
        </div>

        <div class="footer-section newsletter">
            <h3>Newsletter</h3>
            <p>Suscríbete para recibir las últimas novedades.</p>
            <form class="newsletter-form">
                <input type="email" placeholder="Tu correo electrónico" required>
                <button type="submit"><i class="fas fa-paper-plane"></i></button>
            </form>
        </div>
    </div>
    <div class="footer-bottom">
        &copy; ${a} KDTekh. Todos los derechos reservados. | 
        <a href="politica-privacidad.html">Política de Privacidad</a> | 
        <a href="terminos-condiciones.html">Términos y Condiciones</a>
    </div>`}function loadFooter(a){var e,a=document.getElementById(a);a&&(e=renderFooter(),a.innerHTML='<footer class="footer"><div class="container">'+e+"</div></footer>")}document.addEventListener("DOMContentLoaded",function(){var a=document.querySelector("footer");a&&(a.innerHTML=renderFooter())});